def conjugate(verb):
    verb_lower = verb.lower()

    if verb_lower.endswith('ar'):
        root = verb_lower[:-2]
        suffixes = ['o', 'as', 'a', 'amos', 'ais', 'an']
    elif verb_lower.endswith('er'):
        root = verb_lower[:-2]
        suffixes = ['', 'es', 'e', 'emos', 'eis', 'en']
    elif verb_lower.endswith('ir'):
        root = verb_lower[:-2]
        suffixes = [], 'es', 'e', 'imos', 'is', 'en'
    else:
        raise ValueError("Invalid infinitive suffix")

    if verb_lower.endswith('er') or verb_lower.endswith('ir'):
        suffixes[0] = 'o'

    conjugations = [root + s for s in suffixes]

    return {verb_lower: conjugations}
